import data from './placeholder-images.json';

export type ImagePlaceholder = {
  id: string;
  description: string;
  imageUrl: string;
  imageHint: string;
};

export const PlaceHolderImages: ImagePlaceholder[] = data.placeholderImages;

export const fintechCarouselImages: ImagePlaceholder[] =
  data.placeholderImages.filter((img) => img.id.startsWith('fintech-carousel'));
